    "evolution_history": EVOLUTION_HISTORY_TEMPLATE,
    "previous_attempt": PREVIOUS_ATTEMPT_TEMPLATE,
    "top_program": TOP_PROGRAM_TEMPLATE,
    "inspirations_section": INSPIRATIONS_SECTION_TEMPLATE,
    "inspiration_program": INSPIRATION_PROGRAM_TEMPLATE,
    "evaluation": EVALUATION_TEMPLATE,
}


class TemplateManager:
    """Manages templates for prompt generation"""

    def __init__(self, template_dir: Optional[str] = None):
        self.templates = DEFAULT_TEMPLATES.copy()

        # Load templates from directory if provided
        if template_dir and os.path.isdir(template_dir):
            self._load_templates_from_dir(template_dir)

    def _load_templates_from_dir(self, template_dir: str) -> None:
        """Load templates from a directory"""
        for file_path in Path(template_dir).glob("*.txt"):
            template_name = file_path.stem
            with open(file_path, "r") as f:
                self.templates[template_name] = f.read()

    def get_template(self, template_name: str) -> str:
        """Get a template by name"""
        if template_name not in self.templates:
            raise ValueError(f"Template '{template_name}' not found")
        return self.templates[template_name]

    def add_template(self, template_name: str, template: str) -> None:
        """Add or update a template"""
        self.templates[template_name] = template

"""
Utility functions for formatting output
"""

from typing import Any, Dict


def format_metrics_safe(metrics: Dict[str, Any]) -> str:
    """
    Safely format metrics dictionary for logging, handling both numeric and string values.

    Args:
        metrics: Dictionary of metric names to values

    Returns:
        Formatted string representation of metrics
    """
    if not metrics:
        return ""

    formatted_parts = []
    for name, value in metrics.items():
        # Check if value is numeric (int, float)
        if isinstance(value, (int, float)):
            try:
                # Only apply float formatting to numeric values
                formatted_parts.append(f"{name}={value:.4f}")
            except (ValueError, TypeError):
                # Fallback to string representation if formatting fails
                formatted_parts.append(f"{name}={value}")
        else:
            # For non-numeric values (strings, etc.), just convert to string
            formatted_parts.append(f"{name}={value}")

    return ", ".join(formatted_parts)


def format_improvement_safe(parent_metrics: Dict[str, Any], child_metrics: Dict[str, Any]) -> str:
    """
    Safely format improvement metrics for logging.

    Args:
        parent_metrics: Parent program metrics
        child_metrics: Child program metrics

    Returns:
        Formatted string representation of improvements
    """
    if not parent_metrics or not child_metrics:
        return ""

    improvement_parts = []
    for metric, child_value in child_metrics.items():
        if metric in parent_metrics:
            parent_value = parent_metrics[metric]
            # Only calculate improvement for numeric values
            if isinstance(child_value, (int, float)) and isinstance(parent_value, (int, float)):
                try:
                    diff = child_value - parent_value
                    improvement_parts.append(f"{metric}={diff:+.4f}")
                except (ValueError, TypeError):
                    # Skip non-numeric comparisons
                    continue

    return ", ".join(improvement_parts)

"""
Safe calculation utilities for metrics containing mixed types
"""

from typing import Any, Dict


def safe_numeric_average(metrics: Dict[str, Any]) -> float:
    """
    Calculate the average of numeric values in a metrics dictionary,
    safely ignoring non-numeric values like strings.

    Args:
        metrics: Dictionary of metric names to values

    Returns:
        Average of numeric values, or 0.0 if no numeric values found
    """
    if not metrics:
        return 0.0

    numeric_values = []
    for value in metrics.values():
        if isinstance(value, (int, float)):
            try:
                # Convert to float and check if it's a valid number
                float_val = float(value)
                if not (float_val != float_val):  # Check for NaN (NaN != NaN is True)
                    numeric_values.append(float_val)
            except (ValueError, TypeError, OverflowError):
                # Skip invalid numeric values
                continue

    if not numeric_values:
        return 0.0

    return sum(numeric_values) / len(numeric_values)


def safe_numeric_sum(metrics: Dict[str, Any]) -> float:
    """
    Calculate the sum of numeric values in a metrics dictionary,
    safely ignoring non-numeric values like strings.

    Args:
        metrics: Dictionary of metric names to values

    Returns:
        Sum of numeric values, or 0.0 if no numeric values found
    """
    if not metrics:
        return 0.0

    numeric_sum = 0.0
    for value in metrics.values():
        if isinstance(value, (int, float)):
            try:
                # Convert to float and check if it's a valid number
                float_val = float(value)
                if not (float_val != float_val):  # Check for NaN (NaN != NaN is True)
                    numeric_sum += float_val
            except (ValueError, TypeError, OverflowError):
                # Skip invalid numeric values
                continue

    return numeric_sum

"""
Quality gates validation service for code evolution
"""

import ast
import logging
import re
import subprocess
import tempfile
from pathlib import Path
from typing import Dict, List, Any, Optional
import asyncio

from models.evolution_models import QualityGateResult
from config.settings import settings

logger = logging.getLogger(__name__)


class QualityGatesService:
    """Service for validating code quality through various gates"""

    def __init__(self):
        self.validation_stats = {
            "total_validations": 0,
            "syntax_validations": 0,
            "metric_validations": 0,
            "passed_validations": 0,
            "failed_validations": 0,
        }

    async def validate_input_code(self, code: str, language: str) -> QualityGateResult:
        """Validate input code before evolution"""

        self.validation_stats["total_validations"] += 1

        try:
            # Basic syntax validation
            if not await self._validate_syntax(code, language):
                self.validation_stats["failed_validations"] += 1
                return QualityGateResult(
                    gate_name="input_syntax_validation",
                    passed=False,
                    error_message="Input code contains syntax errors"
                )

            # Basic structure validation
            structure_result = await self._validate_code_structure(code, language)
            if not structure_result["passed"]:
                self.validation_stats["failed_validations"] += 1
                return QualityGateResult(
                    gate_name="input_structure_validation",
                    passed=False,
                    error_message=structure_result["error"]
                )

            self.validation_stats["passed_validations"] += 1
            return QualityGateResult(
                gate_name="input_validation",
                passed=True,
                score=1.0,
                details={"checks_passed": ["syntax", "structure"]}
            )

        except Exception as e:
            logger.error(f"Error in input validation: {e}")
            self.validation_stats["failed_validations"] += 1
            return QualityGateResult(
                gate_name="input_validation",
                passed=False,
                error_message=f"Validation error: {str(e)}"
            )

    async def validate_evolved_code(
        self, 
        code: str, 
        language: str,
        original_code: str = None
    ) -> List[QualityGateResult]:
        """Validate evolved code through multiple quality gates"""

        results = []

        # Gate 1: Syntax validation
        syntax_result = await self._run_syntax_gate(code, language)
        results.append(syntax_result)

        # Gate 2: Complexity analysis
        complexity_result = await self._run_complexity_gate(code, language, original_code)
        results.append(complexity_result)

        # Gate 3: Security basic checks
        security_result = await self._run_security_gate(code, language)
        results.append(security_result)

        # Gate 4: Performance indicators
        performance_result = await self._run_performance_gate(code, language)
        results.append(performance_result)

        # Update statistics
        self.validation_stats["total_validations"] += len(results)
        self.validation_stats["passed_validations"] += sum(1 for r in results if r.passed)
        self.validation_stats["failed_validations"] += sum(1 for r in results if not r.passed)

        return results

    async def _run_syntax_gate(self, code: str, language: str) -> QualityGateResult:
        """Validate code syntax"""

        self.validation_stats["syntax_validations"] += 1

        try:
            is_valid = await self._validate_syntax(code, language)

            return QualityGateResult(
                gate_name="syntax_validation",
                passed=is_valid,
                score=1.0 if is_valid else 0.0,
                details={"language": language, "check_type": "syntax"}
            )

        except Exception as e:
            return QualityGateResult(
                gate_name="syntax_validation",
                passed=False,
                error_message=f"Syntax validation error: {str(e)}"
            )

    async def _run_complexity_gate(
        self, 
        code: str, 
        language: str,
        original_code: str = None
    ) -> QualityGateResult:
        """Validate code complexity metrics"""

        try:
            complexity_metrics = await self._calculate_complexity(code, language)

            # Check against thresholds
            max_complexity_increase = settings.quality_gates.max_complexity_increase

            # Basic complexity validation
            passed = True
            details = complexity_metrics.copy()

            if original_code:
                original_metrics = await self._calculate_complexity(original_code, language)

                # Compare complexity increase
                if "cyclomatic_complexity" in complexity_metrics and "cyclomatic_complexity" in original_metrics:
                    complexity_increase = (
                        complexity_metrics["cyclomatic_complexity"] - 
                        original_metrics["cyclomatic_complexity"]
                    ) / max(original_metrics["cyclomatic_complexity"], 1)

                    details["complexity_increase"] = complexity_increase

                    if complexity_increase > max_complexity_increase:
                        passed = False

            # Basic thresholds (can be enhanced)
            if complexity_metrics.get("cyclomatic_complexity", 0) > 20:
                passed = False
                details["threshold_exceeded"] = "cyclomatic_complexity > 20"

            return QualityGateResult(
                gate_name="complexity_validation",
                passed=passed,
                score=1.0 - min(complexity_metrics.get("cyclomatic_complexity", 0) / 30, 1.0),
                details=details
            )

        except Exception as e:
            return QualityGateResult(
                gate_name="complexity_validation",
                passed=True,  # Don't fail on analysis errors
                score=0.5,
                error_message=f"Complexity analysis error: {str(e)}"
            )

    async def _run_security_gate(self, code: str, language: str) -> QualityGateResult:
        """Basic security validation"""

        try:
            security_issues = []

            # Basic security patterns (can be enhanced)
            dangerous_patterns = {
                "eval": r"\beval\s*\(",
                "exec": r"\bexec\s*\(",
                "input_injection": r"input\s*\([^)]*\+",
                "shell_injection": r"os\.system\s*\(",
                "subprocess_shell": r"subprocess\..*shell\s*=\s*True",
            }

            for issue_type, pattern in dangerous_patterns.items():
                if re.search(pattern, code):
                    security_issues.append(issue_type)

            passed = len(security_issues) == 0
            score = 1.0 - (len(security_issues) / len(dangerous_patterns))

            return QualityGateResult(
                gate_name="security_validation",
                passed=passed,
                score=score,
                details={
                    "issues_found": security_issues,
                    "patterns_checked": len(dangerous_patterns)
                }
            )

        except Exception as e:
            return QualityGateResult(
                gate_name="security_validation",
                passed=True,  # Don't fail on analysis errors
                score=0.8,
                error_message=f"Security analysis error: {str(e)}"
            )

    async def _run_performance_gate(self, code: str, language: str) -> QualityGateResult:
        """Basic performance indicators validation"""

        try:
            performance_score = 1.0
            details = {}

            # Simple performance indicators
            if language.lower() == "python":
                # Check for potential performance issues
                performance_issues = []

                # Nested loops
                nested_loop_count = len(re.findall(r'for.*:\s*.*for.*:', code, re.MULTILINE))
                if nested_loop_count > 2:
                    performance_issues.append("excessive_nested_loops")
                    performance_score -= 0.2

                # List comprehensions vs loops (positive indicator)
                list_comp_count = len(re.findall(r'\[.*for.*in.*\]', code))
                details["list_comprehensions"] = list_comp_count

                # String concatenation in loops (negative indicator)
                if re.search(r'for.*:\s*.*\+=.*', code):
                    performance_issues.append("string_concatenation_in_loop")
                    performance_score -= 0.3

                details["performance_issues"] = performance_issues

            # Line count as basic complexity indicator
            line_count = len(code.splitlines())
            details["line_count"] = line_count

            if line_count > 1000:
                performance_score -= 0.1

            return QualityGateResult(
                gate_name="performance_validation",
                passed=performance_score >= 0.6,
                score=max(performance_score, 0.0),
                details=details
            )

        except Exception as e:
            return QualityGateResult(
                gate_name="performance_validation",
                passed=True,  # Don't fail on analysis errors
                score=0.7,
                error_message=f"Performance analysis error: {str(e)}"
            )

    async def _validate_syntax(self, code: str, language: str) -> bool:
        """Validate code syntax"""

        if language.lower() == "python":
            try:
                ast.parse(code)
                return True
            except SyntaxError:
                return False

        elif language.lower() == "javascript":
            # For JavaScript, we could use Node.js syntax check
            # For now, basic validation
            try:
                # Basic bracket matching
                brackets = {"(": ")", "[": "]", "{": "}"}
                stack = []

                for char in code:
                    if char in brackets:
                        stack.append(char)
                    elif char in brackets.values():
                        if not stack or brackets[stack.pop()] != char:
                            return False

                return len(stack) == 0
            except:
                return False

        else:
            # For other languages, assume valid for now
            return True

    async def _validate_code_structure(self, code: str, language: str) -> Dict[str, Any]:
        """Validate basic code structure"""

        try:
            lines = code.split('\n')
            non_empty_lines = [line for line in lines if line.strip()]

            if len(non_empty_lines) < 3:
                return {"passed": False, "error": "Code too short"}

            if language.lower() == "python":
                # Check for basic Python structure
                has_function_or_class = any(
                    line.strip().startswith(('def ', 'class ', 'async def '))
                    for line in non_empty_lines
                )

                if not has_function_or_class:
                    # Allow scripts without functions/classes
                    pass

            return {"passed": True}

        except Exception as e:
            return {"passed": False, "error": f"Structure validation error: {str(e)}"}

    async def _calculate_complexity(self, code: str, language: str) -> Dict[str, Any]:
        """Calculate basic complexity metrics"""

        metrics = {
            "line_count": len(code.splitlines()),
            "non_empty_line_count": len([l for l in code.splitlines() if l.strip()]),
        }

        if language.lower() == "python":
            try:
                # Basic cyclomatic complexity calculation
                complexity_indicators = [
                    r'\bif\b', r'\bwhile\b', r'\bfor\b', 
                    r'\btry\b', r'\bexcept\b', r'\belif\b'
                ]

                complexity = 1  # Base complexity
                for pattern in complexity_indicators:
                    complexity += len(re.findall(pattern, code))

                metrics["cyclomatic_complexity"] = complexity

                # Function count
                function_count = len(re.findall(r'def\s+\w+', code))
                metrics["function_count"] = function_count

                # Class count
                class_count = len(re.findall(r'class\s+\w+', code))
                metrics["class_count"] = class_count

            except Exception as e:
                logger.warning(f"Error calculating Python complexity: {e}")

        return metrics

    def get_validation_stats(self) -> Dict[str, Any]:
        """Get validation statistics"""

        total = max(self.validation_stats["total_validations"], 1)

        return {
            **self.validation_stats,
            "success_rate": self.validation_stats["passed_validations"] / total,
            "failure_rate": self.validation_stats["failed_validations"] / total,
        }

    def reset_stats(self) -> None:
        """Reset validation statistics"""

        self.validation_stats = {
            "total_validations": 0,
            "syntax_validations": 0,
            "metric_validations": 0,
            "passed_validations": 0,
            "failed_validations": 0,
        }

