print(f"📊 Status: {status}")
if status == "completed": # Get results results_response = await client.get(f"{OPENEVOLVE_ENDPOINT}/evolution/{job_id}/results")
if results_response.status_code == 200: results_data = results_response.json() return { "success": True, "job_id": job_id, "results": results_data['data'], "example_name": example_name } else: print(f"❌ Failed to get results: {results_response.status_code}") return {"success": False, "error": "Failed to get results"}
elif status in ["failed", "cancelled"]: print(f"❌ Evolution {status}") return {"success": False, "error": f"Evolution {status}"}
await asyncio.sleep(check_interval) elapsed_time += check_interval
print(f"⏰ Timeout reached ({max_wait_time}s)") return {"success": False, "error": "Timeout waiting for evolution to complete"}
except Exception as e: print(f"💥 Exception during evolution: {e}") return {"success": False, "error": str(e)}
