                }

                completion_response = await client.post(
                    f"{LITELLM_ENDPOINT}/v1/chat/completions",
                    json=completion_request,
                    headers={"Authorization": "Bearer test-master-key"}
                )

                print(f"   Status: {completion_response.status_code}")
                if completion_response.status_code == 200:
                    completion_data = completion_response.json()
                    message = completion_data.get('choices', [{}])[0].get('message', {}).get('content', 'No response')
                    print(f"   AI Response: {message}")
                else:
                    print(f"   Error: {completion_response.text}")

            except Exception as e:
                print(f"   Exception: {e}")

    except Exception as e:
        print(f"💥 Connection failed: {e}")

async def main():
    await test_litellm_direct()

if __name__ == "__main__":
    asyncio.run(main())

