class TestCachedSecret: """Test CachedSecret dataclass"""
def test_cached_secret_not_expired(self): """Test that a recently cached secret is not expired""" secret = CachedSecret( value="test-secret", cached_at=datetime.utcnow(), ttl_seconds=3600 ) assert not secret.is_expired
def test_cached_secret_expired(self): """Test that an old cached secret is expired""" secret = CachedSecret( value="test-secret", cached_at=datetime.utcnow() - timedelta(seconds=7200), # 2 hours ago ttl_seconds=3600 # 1 hour TTL ) assert secret.is_expired
class TestCircuitBreaker: """Test CircuitBreaker functionality"""
def test_initial_state(self): """Test circuit breaker initial state""" cb = CircuitBreaker() assert cb.state == CircuitBreakerState.CLOSED assert cb.failure_count == 0 assert cb.can_attempt() is True
def test_record_success(self): """Test recording successful operations""" cb = CircuitBreaker() cb.failure_count = 3 cb.record_success()
assert cb.failure_count == 0 assert cb.state == CircuitBreakerState.CLOSED
def test_record_failure_opens_circuit(self): """Test that repeated failures open the circuit""" cb = CircuitBreaker(failure_threshold=3)
# Record failures below threshold for i in range(2): cb.record_failure() assert cb.state == CircuitBreakerState.CLOSED
# Record failure that opens circuit cb.record_failure() assert cb.state == CircuitBreakerState.OPEN assert cb.can_attempt() is False
def test_half_open_recovery(self): """Test circuit breaker recovery to half-open state""" cb = CircuitBreaker(failure_threshold=2, recovery_timeout=1)
# Open the circuit cb.record_failure() cb.record_failure() assert cb.state == CircuitBreakerState.OPEN
# Wait for recovery timeout import time time.sleep(1.1)
# Should allow attempt and be in half-open state assert cb.can_attempt() is True
