def _static_validate_metal_kernel_syntax(self, program_text: str) -> Dict[str, Any]: """Static analysis of Metal kernel syntax for common safety issues""" warnings = []
# Check for common Metal safety issues dangerous_patterns = [ ("buffer overflow", ["queries[", "keys[", "values[", "output[", "mask["]), ("unguarded loops", ["for (", "while ("]), ("raw pointers", ["*queries", "*keys", "*values", "*output"]), ("thread sync issues", ["threadgroup", "simdgroup"]), ]
for issue_type, patterns in dangerous_patterns: for pattern in patterns: if pattern in program_text: warnings.append(f"{issue_type}: {pattern}")
# Check for bounds checking has_bounds_checking = any( check in program_text for check in [ "batch_idx >= BATCH_SIZE", "head_idx >= NUM_HEADS", "query_pos >= SEQ_LEN", "d < HEAD_DIM", ] )
if not has_bounds_checking: warnings.append("missing bounds checking")
return { "safe": len(warnings) == 0, "warnings": warnings, "has_bounds_checking": has_bounds_checking, }
def _validate_custom_attention_class(self, custom_class: Any) -> Dict[str, Any]: """Comprehensive validation of custom attention class""" try: # Basic type checking if not isinstance(custom_class, type): return {"valid": False, "error": "CustomGQAAttention is not a valid class"}
# Check for required methods required_methods = ["__init__", "__call__"] for method in required_methods: if not hasattr(custom_class, method): return {"valid": False, "error": f"Missing required method: {method}"}
# Check if it inherits from nn.Module (recommended) if not issubclass(custom_class, nn.Module): print(" ⚠️ CustomGQAAttention doesn't inherit from nn.Module")
print(" ✅ Custom attention class validation passed") return {"valid": True}
except Exception as e: return {"valid": False, "error": f"Class validation error: {e}"}
def _validate_metal_kernel_safety(self, custom_attention_class: Any) -> Dict[str, Any]: """Pre-execution validation of Metal kernel safety""" try: print(" 🔍 Validating Metal kernel safety parameters...")
# Mock arguments for safety testing class MockArgs: hidden_size = 5120 num_attention_heads = 40 num_key_value_heads = 8 head_dim = 128 rms_norm_eps = 1e-06 rope_theta = 1000000 rope_scaling = None max_position_embeddings = 40960
args = MockArgs()
# Try to instantiate with safety checks try: instance = custom_attention_class(args) if instance is None: return {"success": False, "error": "Failed to instantiate custom attention"}
print(" ✅ Custom attention instantiation successful")
# Basic parameter validation if hasattr(instance, "n_heads") and instance.n_heads != 40: return {"success": False, "error": f"Invalid head count: {instance.n_heads}"}
if hasattr(instance, "n_kv_heads") and instance.n_kv_heads != 8: return { "success": False, "error": f"Invalid KV head count: {instance.n_kv_heads}", }
return {"success": True, "validated": True}
except Exception as e: error_msg = str(e) if any(keyword in error_msg.lower() for keyword in ["metal", "kernel", "gpu"]): self.metal_compilation_errors += 1 return {"success": False, "error": f"Instantiation failed: {error_msg}"}
except Exception as e: self.total_metal_errors += 1 return {"success": False, "error": f"Safety validation error: {e}"}
def _bulletproof_execute_with_gpu_protection(self, func) -> Tuple[bool, Any]: """Execute function with maximum GPU and Metal kernel protection""" try: # Clear any existing GPU state mx.eval(mx.array([1.0])) # Simple operation to ensure GPU is responsive
# Execute with comprehensive error catching result = func() return True, result
except RuntimeError as e: error_msg = str(e)
# Classify specific Metal/GPU errors if "kIOGPUCommandBufferCallbackErrorInvalidResource" in error_msg: self.metal_command_buffer_errors += 1 self.total_metal_errors += 1 return False, f"GPU Command Buffer Error (memory violation): {error_msg}" elif "METAL" in error_msg.upper(): self.metal_memory_violations += 1 self.total_metal_errors += 1 return False, f"Metal Memory Violation: {error_msg}" elif any(keyword in error_msg.lower() for keyword in ["gpu", "metal", "kernel"]): self.gpu_resource_errors += 1 self.total_metal_errors += 1 return False, f"GPU Resource Error: {error_msg}" else: return False, f"Runtime Error: {error_msg}"
except Exception as e: error_msg = str(e)
# Additional classification for other Metal-related exceptions if any( keyword in error_msg.lower() for keyword in ["metal", "kernel", "gpu", "mps", "mtl"] ): self.total_metal_errors += 1 return False, f"General Metal Error: {error_msg}" else: return False, f"Execution Error: {error_msg}"
def _gpu_protected_measure_baseline(self) -> Optional[List[BenchmarkResult]]: """GPU-protected baseline measurement with enhanced error handling""" try: print(" 📊 Running GPU-protected baseline benchmark...")
# Ensure clean GPU state self._ensure_clean_gpu_state() self._ensure_standard_attention()
# Get baseline configurations baseline_configs = self._get_safe_benchmark_configs() if not baseline_configs: print(" ❌ No safe benchmark configurations available") return None
baseline_results = [] successful_count = 0
for i, config in enumerate(baseline_configs, 1): print(f" [{i}/{len(baseline_configs)}] GPU-protected baseline: {config.name}")
retry_count = 0 while retry_count <= self.max_retry_attempts: try: # Clean GPU state before each attempt self._ensure_clean_gpu_state()
# Run with GPU protection success, result = self._bulletproof_execute_with_gpu_protection( lambda: self.benchmark_suite.run_single_benchmark(config) )
if success and result: baseline_results.append(result) successful_count += 1 print( f" ✅ GPU-protected {config.name}: {result.decode_tokens_per_sec:.1f} tokens/sec" ) break else: if retry_count < self.max_retry_attempts: print(f" 🔄 Retry {retry_count + 1}: {result}") retry_count += 1 time.sleep(self.retry_base_delay * (2**retry_count)) continue else: print(f" ❌ All retries exhausted for {config.name}: {result}") break
except Exception as e: if retry_count < self.max_retry_attempts: print(f" 🔄 Exception retry {retry_count + 1}: {e}") retry_count += 1 time.sleep(self.retry_base_delay * (2**retry_count)) continue else: print(f" ❌ Final exception for {config.name}: {e}") break
# Check success rate min_required = max(2, len(baseline_configs) * 0.5) # At least 50% success if successful_count < min_required: print( f" ❌ Insufficient baseline results: {successful_count}/{len(baseline_configs)}" ) return None
# Store baseline metrics self._store_enhanced_baseline_metrics(baseline_results) print(f" ✅ GPU-protected baseline complete ({successful_count} successful)")
return baseline_results
except Exception as e: print(f" ❌ GPU-protected baseline measurement failed: {e}") return None
def _memory_safe_correctness_test(self, custom_attention_class: Any) -> Dict[str, Any]: """Memory-safe correctness testing with GPU protection""" print(" 🔍 Running memory-safe correctness testing...")
try: # Safe test configuration class MockArgs: hidden_size = 5120 num_attention_heads = 40 num_key_value_heads = 8 head_dim = 128 rms_norm_eps = 1e-06 rope_theta = 1000000 rope_scaling = None max_position_embeddings = 40960
args = MockArgs()
# Conservative test cases (smaller sequences for safety) test_cases = [ (1, 8, 5120), # Micro sequence (1, 16, 5120), # Very short (1, 32, 5120), # Short sequence (1, 64, 5120), # Medium sequence ]
correctness_scores = [] local_command_buffer_errors = 0 local_memory_violations = 0
for B, L, D in test_cases: print(f" 🧪 Memory-safe testing sequence length {L}...")
retry_count = 0 while retry_count <= self.max_retry_attempts: try: # Clean GPU state self._ensure_clean_gpu_state()
# Create conservative test inputs x = mx.random.normal((B, L, D)) * 0.1 # Smaller values for safety mask = "causal"
# Test with maximum GPU protection success, result = self._bulletproof_execute_with_gpu_protection( lambda: self._test_single_sequence_memory_safe( custom_attention_class, args, x, mask ) )
if success: correctness_scores.append(result) print(f" ✅ Sequence {L}: PASS (score={result:.3f})") break else: error_msg = str(result)
# Enhanced error classification if "command buffer" in error_msg.lower(): local_command_buffer_errors += 1 elif "memory violation" in error_msg.lower(): local_memory_violations += 1
if retry_count < self.max_retry_attempts: print( f" 🔄 Retry {retry_count + 1} for length {L}: {error_msg}" ) retry_count += 1 time.sleep(self.retry_base_delay * (2**retry_count)) continue else: print(f" ❌ All retries failed for length {L}: {error_msg}") correctness_scores.append(0.0) break
except Exception as e: error_msg = str(e) print(f" ❌ Exception for length {L}: {error_msg}")
if retry_count < self.max_retry_attempts: retry_count += 1 time.sleep(self.retry_base_delay * (2**retry_count)) continue else: correctness_scores.append(0.0) break
# Update global error counters self.metal_command_buffer_errors += local_command_buffer_errors self.metal_memory_violations += local_memory_violations self.total_metal_errors += local_command_buffer_errors + local_memory_violations
# Calculate overall correctness with partial credit overall_correctness = np.mean(correctness_scores) if correctness_scores else 0.0
print(f" 📊 Memory-safe overall correctness: {overall_correctness:.3f}") print(f" 🛡️ Command buffer errors: {local_command_buffer_errors}") print(f" 🛡️ Memory violations: {local_memory_violations}")
return { "success": True, "score": overall_correctness, "command_buffer_errors": local_command_buffer_errors, "memory_violations": local_memory_violations, }
except Exception as e: self.total_metal_errors += 1 print(f" ❌ Memory-safe correctness testing failed: {e}") return {"success": False, "error": str(e)}
def _test_single_sequence_memory_safe( self, custom_attention_class: Any, args: Any, x: Any, mask: Any ) -> float: """Test single sequence with enhanced memory safety""" try: # Pre-execution safety checks if x.shape[1] > self.max_sequence_length_safe: raise MetalKernelSafetyError( f"Sequence length {x.shape[1]} exceeds safe limit {self.max_sequence_length_safe}" )
if x.shape[0] > self.max_batch_size_safe: raise MetalKernelSafetyError( f"Batch size {x.shape[0]} exceeds safe limit {self.max_batch_size_safe}" )
# Instantiate with error checking custom_attn = custom_attention_class(args) if custom_attn is None: raise ValueError("Failed to instantiate custom attention")
# Conservative forward pass with timeout simulation start_time = time.time() output = custom_attn(x, mask=mask) elapsed_time = time.time() - start_time
# Timeout check (soft limit) if elapsed_time > self.kernel_validation_timeout: print(f" ⚠️ Slow execution detected: {elapsed_time:.2f}s") return 0.5 # Partial credit for slow but working kernel
# Enhanced output validation if output is None: raise ValueError("Custom attention returned None")
# Shape validation expected_shape = x.shape if output.shape != expected_shape: raise ValueError(f"Wrong output shape: {output.shape}, expected {expected_shape}")
# Enhanced finite value check finite_mask = mx.isfinite(output) if not mx.all(finite_mask): finite_ratio = float(mx.mean(finite_mask.astype(mx.float32))) if finite_ratio < 0.9: raise ValueError(f"Too many non-finite values: {finite_ratio:.2%} finite") else: print(f" ⚠️ Some non-finite values: {finite_ratio:.2%} finite") return 0.7 # Partial credit
# Enhanced statistical validation output_mean = float(mx.mean(output)) output_std = float(mx.std(output)) output_max = float(mx.max(mx.abs(output)))
# More lenient bounds for complex kernels if abs(output_mean) > 10.0: print(f" ⚠️ Large mean: {output_mean:.6f}") return 0.6
if output_std > 100.0 or output_std < 0.00001: print(f" ⚠️ Unusual std: {output_std:.6f}") return 0.6
if output_max > 1000.0: print(f" ⚠️ Large max value: {output_max:.6f}") return 0.7
# All checks passed return 1.0
except MetalKernelSafetyError as e: raise e # Re-raise safety errors except Exception as e: error_msg = str(e) if any( keyword in error_msg.lower() for keyword in ["metal", "kernel", "gpu", "command buffer"] ): raise GPUCommandBufferError(f"GPU execution error: {error_msg}") else: raise ValueError(f"Sequence test error: {error_msg}")
def _command_buffer_protected_benchmark(self, custom_attention_class: Any) -> Dict[str, Any]: """Command-buffer-protected benchmarking with maximum safety""" print(" 🚀 Running command-buffer-protected benchmarking...")
retry_attempt = 0
while retry_attempt <= self.max_retry_attempts: try: print(f" 🔄 Protected attempt {retry_attempt + 1}/{self.max_retry_attempts + 1}")
# Clean GPU state before each major attempt self._ensure_clean_gpu_state()
# Apply custom attention hook with protection hook_result = self._gpu_protected_apply_hook(custom_attention_class) if not hook_result["success"]: if retry_attempt < self.max_retry_attempts: print(f" 🔄 Hook failed, retrying... ({hook_result['error']})") retry_attempt += 1 time.sleep(self.retry_base_delay * (2**retry_attempt)) continue return { "success": False, "error": f"Hook application failed: {hook_result['error']}", }
original_attention = hook_result["original"]
try: # Run benchmarks with command buffer protection custom_configs = self._get_safe_benchmark_configs() custom_results = [] successful_benchmarks = 0
for i, config in enumerate(custom_configs, 1): print( f" [{i}/{len(custom_configs)}] Command-buffer-protected: {config.name}" )
benchmark_retry = 0 while benchmark_retry <= 2: # Fewer retries per benchmark try: # Clean state before each benchmark self._ensure_clean_gpu_state()
# Run with maximum protection success, result = self._bulletproof_execute_with_gpu_protection( lambda: self.benchmark_suite.run_single_benchmark(config) )
if success and result: custom_results.append(result) successful_benchmarks += 1 print( f" ✅ Protected {config.name}: {result.decode_tokens_per_sec:.1f} tokens/sec" ) break else: if benchmark_retry < 2: print( f" 🔄 Benchmark retry {benchmark_retry + 1}: {result}" ) benchmark_retry += 1 time.sleep(1) continue else: print(f" ❌ Benchmark failed: {result}") break
except Exception as e: if benchmark_retry < 2: print( f" 🔄 Benchmark exception retry {benchmark_retry + 1}: {e}" ) benchmark_retry += 1 time.sleep(1) continue else: print(f" ❌ Benchmark exception: {e}") break
# Check success rate min_required = max(2, len(custom_configs) * 0.4) # Lowered to 40% for safety if successful_benchmarks >= min_required: print( f" ✅ Command-buffer-protected benchmarks complete ({successful_benchmarks} successful)" ) self.retry_attempts_used = retry_attempt return {"success": True, "results": custom_results} else: error_msg = f"Insufficient benchmarks: {successful_benchmarks}/{len(custom_configs)} succeeded" if retry_attempt < self.max_retry_attempts: print(f" 🔄 {error_msg}, retrying full attempt...") retry_attempt += 1 time.sleep(self.retry_base_delay * (2**retry_attempt)) continue return {"success": False, "error": error_msg}
finally: # Always restore original attention self._gpu_protected_remove_hook(original_attention)
except Exception as e: error_msg = f"Command-buffer-protected attempt failed: {str(e)}" print(f" ❌ {error_msg}") if retry_attempt < self.max_retry_attempts: retry_attempt += 1 time.sleep(self.retry_base_delay * (2**retry_attempt)) continue return {"success": False, "error": error_msg}
return {"success": False, "error": "All command-buffer-protected attempts exhausted"}
def _ensure_clean_gpu_state(self): """Ensure clean GPU state before operations""" try: # Simple operation to ensure GPU responsiveness test_op = mx.array([1.0, 2.0, 3.0]) mx.eval(test_op * 2)
# Small delay to let GPU settle time.sleep(0.1)
except Exception as e: print(f" ⚠️ GPU state cleanup warning: {e}")
def _gpu_protected_apply_hook(self, custom_attention_class: Any) -> Dict[str, Any]: """GPU-protected application of custom attention hook""" try: success, result = self._bulletproof_execute_with_gpu_protection( lambda: self._apply_attention_hook_safely(custom_attention_class) )
if success: return {"success": True, "original": result} else: return {"success": False, "error": result}
except Exception as e: return {"success": False, "error": f"GPU-protected hook application failed: {e}"}
def _apply_attention_hook_safely(self, custom_attention_class: Any) -> Any: """Safely apply attention hook""" import mlx_lm.models.qwen3 as qwen3_module
# Store original attention class original_attention = getattr(qwen3_module, "Attention", None) if original_attention is None: raise RuntimeError("Could not find original Attention class")
# Apply custom attention qwen3_module.Attention = custom_attention_class
# Verify the hook was applied if qwen3_module.Attention != custom_attention_class: raise RuntimeError("Hook application verification failed")
print(" ✅ Custom attention hook applied with GPU protection") return original_attention
def _gpu_protected_remove_hook(self, original_attention: Any): """GPU-protected removal of custom attention hook""" try: success, result = self._bulletproof_execute_with_gpu_protection( lambda: self._remove_attention_hook_safely(original_attention) )
if not success: print(f" ⚠️ Hook removal warning: {result}")
except Exception as e: print(f" ⚠️ Hook removal error (non-fatal): {e}")
def _remove_attention_hook_safely(self, original_attention: Any): """Safely remove attention hook""" import mlx_lm.models.qwen3 as qwen3_module
qwen3_module.Attention = original_attention print(" ✅ Hook removed with GPU protection")
def _create_bulletproof_execution_environment(self) -> Dict[str, Any]: """Create bulletproof execution environment with enhanced imports""" import math import numpy as np import time from typing import Optional, Tuple, Any
exec_globals = { "__builtins__": __builtins__, "mx": mx, "nn": nn, "np": np, "math": math, "time": time, "Optional": Optional, "Tuple": Tuple, "Any": Any, }
# Enhanced MLX-LM import with error handling try: exec_globals["mlx_lm"] = __import__("mlx_lm") print(" ✅ MLX-LM imported for bulletproof execution") except ImportError: print(" ⚠️ MLX-LM not available for bulletproof execution") except Exception as e: print(f" ⚠️ MLX-LM import error in bulletproof environment: {e}")
return exec_globals
def _get_safe_benchmark_configs(self) -> List[BenchmarkConfig]: """Get safer benchmark configurations for GPU protection""" try: all_configs = self.benchmark_suite.create_benchmark_configs()
# Use more conservative test set for safety safe_test_names = [ "short_context_quick", # Safest - very short "code_generation", # Medium safety "long_context_detailed", # More challenging but still safe "long_generation", # Longer generation "maximum_context_stress_test", # Most challenging - saved for last ]
config_dict = {c.name: c for c in all_configs} safe_configs = []
for test_name in safe_test_names: if test_name in config_dict: safe_configs.append(config_dict[test_name])
return safe_configs
except Exception as e: print(f" ⚠️ Error getting safe benchmark configs: {e}") return []
def _ensure_standard_attention(self): """Ensure standard attention is active""" try: import mlx_lm.models.qwen3 as qwen3_module
if hasattr(self, "_original_attention") and self._original_attention: qwen3_module.Attention = self._original_attention print(" 🔄 Restored standard attention for baseline") except ImportError: print(" ⚠️ Could not access qwen3 module for standard attention")
def _store_enhanced_baseline_metrics(self, baseline_results: List[BenchmarkResult]): """Store enhanced baseline metrics""" decode_speeds = [ r.decode_tokens_per_sec for r in baseline_results if r.decode_tokens_per_sec > 0 ] prefill_speeds = [ r.prefill_tokens_per_sec for r in baseline_results if r.prefill_tokens_per_sec > 0 ] memories = [r.peak_memory_gb for r in baseline_results if r.peak_memory_gb > 0]
self.baseline_results = baseline_results self.baseline_metrics = { "avg_decode_speed": float(np.mean(decode_speeds)) if decode_speeds else 0.0, "min_decode_speed": float(np.min(decode_speeds)) if decode_speeds else 0.0, "max_decode_speed": float(np.max(decode_speeds)) if decode_speeds else 0.0, "std_decode_speed": float(np.std(decode_speeds)) if len(decode_speeds) > 1 else 0.0, "avg_prefill_speed": float(np.mean(prefill_speeds)) if prefill_speeds else 0.0, "avg_memory_gb": float(np.mean(memories)) if memories else 0.0, "max_memory_gb": float(np.max(memories)) if memories else 0.0, "num_baseline_tests": len(baseline_results), }
print( f" 📊 Enhanced baseline stored - Avg decode: {self.baseline_metrics['avg_decode_speed']:.1f} tokens/sec" )
def _analyze_performance_with_safety_metrics( self, baseline_results: List[BenchmarkResult], custom_results: List[BenchmarkResult] ) -> Dict[str, Any]: """Analyze performance with enhanced safety metrics""" print(" 📈 Analyzing performance with safety metrics...")
baseline_dict = {r.name: r for r in baseline_results} custom_dict = {r.name: r for r in custom_results}
individual_comparisons = [] improvements = { "decode_speed_improvements": [], "prefill_speed_improvements": [], "total_speed_improvements": [], "memory_improvements": [], "time_improvements": [], }
# Compare each benchmark for name in baseline_dict: if name in custom_dict: baseline = baseline_dict[name] custom = custom_dict[name]
# Calculate improvements with safety bounds decode_improvement = self._safe_calculate_improvement( custom.decode_tokens_per_sec, baseline.decode_tokens_per_sec ) prefill_improvement = self._safe_calculate_improvement( custom.prefill_tokens_per_sec, baseline.prefill_tokens_per_sec ) total_improvement = self._safe_calculate_improvement( custom.total_tokens_per_sec, baseline.total_tokens_per_sec ) memory_improvement = self._safe_calculate_improvement( baseline.peak_memory_gb, custom.peak_memory_gb # Reversed for memory ) time_improvement = self._safe_calculate_improvement( baseline.total_time_sec, custom.total_time_sec # Reversed for time )
comparison = { "benchmark_name": name, "baseline": self._result_to_dict(baseline), "custom": self._result_to_dict(custom), "improvements": { "decode_speed_pct": decode_improvement, "prefill_speed_pct": prefill_improvement, "total_speed_pct": total_improvement, "memory_reduction_pct": memory_improvement, "time_reduction_pct": time_improvement, }, }
individual_comparisons.append(comparison)
improvements["decode_speed_improvements"].append(decode_improvement) improvements["prefill_speed_improvements"].append(prefill_improvement) improvements["total_speed_improvements"].append(total_improvement) improvements["memory_improvements"].append(memory_improvement) improvements["time_improvements"].append(time_improvement)
print(f" • {name}: {decode_improvement:+.1f}% decode speed")
# Calculate aggregate statistics with safety checks aggregate_stats = {} for key, values in improvements.items(): if values: # Use robust statistics valid_values = [v for v in values if not np.isnan(v) and not np.isinf(v)] if valid_values: aggregate_stats[f"{key}_avg"] = float(np.mean(valid_values)) aggregate_stats[f"{key}_median"] = float(np.median(valid_values)) aggregate_stats[f"{key}_min"] = float(np.min(valid_values)) aggregate_stats[f"{key}_max"] = float(np.max(valid_values)) aggregate_stats[f"{key}_std"] = float(np.std(valid_values))
# Calculate custom metrics custom_decode_speeds = [ r.decode_tokens_per_sec for r in custom_results if r.decode_tokens_per_sec > 0 ] custom_prefill_speeds = [ r.prefill_tokens_per_sec for r in custom_results if r.prefill_tokens_per_sec > 0 ] custom_memories = [r.peak_memory_gb for r in custom_results if r.peak_memory_gb > 0]
aggregate_metrics = { "avg_decode_speed": ( float(np.mean(custom_decode_speeds)) if custom_decode_speeds else 0.0 ), "min_decode_speed": ( float(np.min(custom_decode_speeds)) if custom_decode_speeds else 0.0 ), "max_decode_speed": ( float(np.max(custom_decode_speeds)) if custom_decode_speeds else 0.0 ), "avg_prefill_speed": ( float(np.mean(custom_prefill_speeds)) if custom_prefill_speeds else 0.0 ), "avg_memory_gb": float(np.mean(custom_memories)) if custom_memories else 0.0, "max_memory_gb": float(np.max(custom_memories)) if custom_memories else 0.0, "num_successful_tests": len(custom_results), "decode_speed_std": ( float(np.std(custom_decode_speeds)) if len(custom_decode_speeds) > 1 else 0.0 ), }
# Enhanced comparison summary comparison_summary = { "avg_decode_improvement_pct": aggregate_stats.get("decode_speed_improvements_avg", 0), "avg_decode_improvement_absolute": ( aggregate_metrics["avg_decode_speed"] - self.baseline_metrics["avg_decode_speed"] ), "memory_change_gb": ( aggregate_metrics["avg_memory_gb"] - self.baseline_metrics["avg_memory_gb"] ), "target_achieved": aggregate_stats.get("decode_speed_improvements_avg", 0) >= 5.0, "num_benchmarks_improved": sum( 1 for x in improvements["decode_speed_improvements"] if x > 1.0 ), # More lenient "total_benchmarks": len(improvements["decode_speed_improvements"]), "safety_score": self._calculate_safety_score(), }
print( f" 📊 Enhanced analysis complete: {comparison_summary['avg_decode_improvement_pct']:+.1f}% avg improvement" ) print(f" 🛡️ Safety score: {comparison_summary['safety_score']:.2f}")
return { "individual_comparisons": individual_comparisons, "aggregate_improvements": aggregate_stats, "aggregate_metrics": aggregate_metrics, "comparison_summary": comparison_summary, }
def _safe_calculate_improvement(self, new_value: float, old_value: float) -> float: """Safely calculate percentage improvement with bounds""" if old_value <= 0 or np.isnan(old_value) or np.isnan(new_value): return 0.0
improvement = (new_value - old_value) / old_value * 100
# Clamp extreme values for safety return max(-100.0, min(1000.0, improvement))
def _calculate_safety_score(self) -> float: """Calculate overall safety score based on error statistics""" total_operations = ( self.metal_command_buffer_errors + self.metal_memory_violations + self.metal_compilation_errors + self.gpu_resource_errors + 10 # Assumed successful operations )
error_rate = self.total_metal_errors / total_operations safety_score = max(0.0, 1.0 - error_rate) * 100
return safety_score
def _calculate_safety_adjusted_score( self, performance_analysis: Dict[str, Any], correctness: float ) -> float: """Calculate final score adjusted for safety""" if correctness < 0.90: return -1000.0
comparison = performance_analysis["comparison_summary"] avg_improvement = comparison["avg_decode_improvement_pct"] memory_change = comparison["memory_change_gb"] success_rate = comparison["num_benchmarks_improved"] / max( 1, comparison["total_benchmarks"] ) safety_score = comparison["safety_score"]
# Enhanced score components performance_score = avg_improvement * 3 # Primary component memory_bonus = max(0, -memory_change * 10) # Bonus for memory reduction consistency_bonus = success_rate * 10 # Bonus for consistent improvements correctness_bonus = correctness * 5 # Bonus for correctness safety_bonus = (safety_score / 100) * 5 # Bonus for safety
# Penalty for excessive errors error_penalty = min(self.total_metal_errors * 2, 20) # Cap penalty
final_score = ( performance_score + memory_bonus + consistency_bonus + correctness_bonus + safety_bonus - error_penalty )
print(f" 🎯 Safety-adjusted score breakdown:") print(f" • Performance: {avg_improvement:.2f}% × 3 = {performance_score:.2f}") print(f" • Memory: {memory_bonus:.2f}") print(f" • Consistency: {success_rate:.2f} × 10 = {consistency_bonus:.2f}") print(f" • Correctness: {correctness:.3f} × 5 = {correctness_bonus:.2f}") print(f" • Safety: {safety_score:.1f}/100 × 5 = {safety_bonus:.2f}") print(f" • Error penalty: -{error_penalty:.2f}") print(f" • Final score: {final_score:.2f}")
return final_score
def _generate_comprehensive_summary( self, performance_analysis: Dict[str, Any], correctness: float ) -> str: """Generate comprehensive evaluation summary with safety info""" comparison = performance_analysis["comparison_summary"] metrics = performance_analysis["aggregate_metrics"]
avg_improvement = comparison["avg_decode_improvement_pct"] current_decode = metrics["avg_decode_speed"] baseline_decode = self.baseline_metrics["avg_decode_speed"] safety_score = comparison["safety_score"]
summary = f"""Bulletproof Custom GQA Implementation Results: • Decode Speed: {current_decode:.1f} tokens/sec (baseline: {baseline_decode:.1f}) • Improvement: {avg_improvement:+.1f}% • Memory Usage: {metrics['avg_memory_gb']:.2f} GB • Correctness: {correctness:.1%} • Safety Score: {safety_score:.1f}/100 • Tests Passed: {metrics['num_successful_tests']}/{len(self._get_safe_benchmark_configs())} • Benchmarks Improved: {comparison['num_benchmarks_improved']}/{comparison['total_benchmarks']} • Metal Errors Handled: {self.total_metal_errors}"""
