class TemplateManager:
    """Manages templates for prompt generation"""

    def __init__(self, template_dir: Optional[str] = None):
        self.templates = DEFAULT_TEMPLATES.copy()

        # Load templates from directory if provided
        if template_dir and os.path.isdir(template_dir):
            self._load_templates_from_dir(template_dir)

    def _load_templates_from_dir(self, template_dir: str) -> None:
        """Load templates from a directory"""
        for file_path in Path(template_dir).glob("*.txt"):
            template_name = file_path.stem
            with open(file_path, "r") as f:
                self.templates[template_name] = f.read()

    def get_template(self, template_name: str) -> str:
        """Get a template by name"""
        if template_name not in self.templates:
            raise ValueError(f"Template '{template_name}' not found")
        return self.templates[template_name]

    def add_template(self, template_name: str, template: str) -> None:
        """Add or update a template"""
        self.templates[template_name] = template

"""
Utility functions for formatting output
"""

from typing import Any, Dict


def format_metrics_safe(metrics: Dict[str, Any]) -> str:
    """
    Safely format metrics dictionary for logging, handling both numeric and string values.

    Args:
        metrics: Dictionary of metric names to values

    Returns:
        Formatted string representation of metrics
    """
    if not metrics:
        return ""

    formatted_parts = []
    for name, value in metrics.items():
        # Check if value is numeric (int, float)
        if isinstance(value, (int, float)):
            try:
                # Only apply float formatting to numeric values
                formatted_parts.append(f"{name}={value:.4f}")
            except (ValueError, TypeError):
                # Fallback to string representation if formatting fails
                formatted_parts.append(f"{name}={value}")
        else:
            # For non-numeric values (strings, etc.), just convert to string
            formatted_parts.append(f"{name}={value}")

    return ", ".join(formatted_parts)


def format_improvement_safe(parent_metrics: Dict[str, Any], child_metrics: Dict[str, Any]) -> str:
    """
    Safely format improvement metrics for logging.

    Args:
        parent_metrics: Parent program metrics
        child_metrics: Child program metrics

    Returns:
        Formatted string representation of improvements
    """
    if not parent_metrics or not child_metrics:
        return ""

    improvement_parts = []
    for metric, child_value in child_metrics.items():
        if metric in parent_metrics:
            parent_value = parent_metrics[metric]
            # Only calculate improvement for numeric values
            if isinstance(child_value, (int, float)) and isinstance(parent_value, (int, float)):
                try:
                    diff = child_value - parent_value
                    improvement_parts.append(f"{metric}={diff:+.4f}")
                except (ValueError, TypeError):
                    # Skip non-numeric comparisons
                    continue

    return ", ".join(improvement_parts)

"""
Safe calculation utilities for metrics containing mixed types
"""

from typing import Any, Dict


def safe_numeric_average(metrics: Dict[str, Any]) -> float:
    """
    Calculate the average of numeric values in a metrics dictionary,
    safely ignoring non-numeric values like strings.

    Args:
        metrics: Dictionary of metric names to values

    Returns:
        Average of numeric values, or 0.0 if no numeric values found
    """
    if not metrics:
        return 0.0

    numeric_values = []
    for value in metrics.values():
        if isinstance(value, (int, float)):
            try:
                # Convert to float and check if it's a valid number
                float_val = float(value)
                if not (float_val != float_val):  # Check for NaN (NaN != NaN is True)
                    numeric_values.append(float_val)
            except (ValueError, TypeError, OverflowError):
                # Skip invalid numeric values
                continue

    if not numeric_values:
        return 0.0

    return sum(numeric_values) / len(numeric_values)


def safe_numeric_sum(metrics: Dict[str, Any]) -> float:
    """
    Calculate the sum of numeric values in a metrics dictionary,
    safely ignoring non-numeric values like strings.

    Args:
        metrics: Dictionary of metric names to values

    Returns:
        Sum of numeric values, or 0.0 if no numeric values found
    """
    if not metrics:
        return 0.0

    numeric_sum = 0.0
    for value in metrics.values():
        if isinstance(value, (int, float)):
            try:
                # Convert to float and check if it's a valid number
                float_val = float(value)
                if not (float_val != float_val):  # Check for NaN (NaN != NaN is True)
                    numeric_sum += float_val
            except (ValueError, TypeError, OverflowError):
                # Skip invalid numeric values
                continue

    return numeric_sum

:root {
    --toolbar-bg: #fff;
    --sidebar-bg: #fff;
    --text-color: #222;
    --node-default: #fff;
    --node-stroke: #fff;
    --sidebar-shadow: -2px 0 24px #aaa;
    --toolbar-shadow: 0 4px 16px #aaa;
    --main-bg: #f7f7f7;
    --tab-bg: #eee;
    --tab-active-bg: #fff;
    --tab-border: #ddd;
    --tab-active-border: #fff;
    --select-bg: #fff;
    --select-color: #222;
    --select-border: #ccc;
    --toolbar-height: 3.5em;
}
[data-theme="dark"] {
    --toolbar-bg: #282a2b;
    --sidebar-bg: #23272a;
    --text-color: #e6eaf3;
    --node-default: #23272a;
    --node-stroke: #3b5ca8;
    --sidebar-shadow: -8px 0 24px #1e3a8ccc;
    --toolbar-shadow: 0 4px 16px #1e3a8ccc;
    --main-bg: #181a1b;
    --tab-bg: #22304a;
    --tab-active-bg: #1e2a3a;
    --tab-border: #3b5ca8;
    --tab-active-border: #3b5ca8;
    --select-bg: #22304a;
    --select-color: #e6eaf3;
    --select-border: #3b5ca8;
    --toolbar-height: 3.5em;
}
html, body {
    height: 100%;
    margin: 0;
    padding: 0 2em;
}
body {
    font-family: Arial, sans-serif;
    background: var(--main-bg);
    color: var(--text-color);
    height: 100vh;
    width: 100vw;
}
h1 span { font-size: 0.5em; color: #666; }
#toolbar {
    display: flex;
    align-items: center;
    flex-direction: row;
    gap: 0.5em;
    padding: 0.7em 1.5em 0.7em 1.5em;
    background: var(--toolbar-bg, #f8f9fa);
    border-bottom: 1.5px solid #e0e0e0;
    z-index: 10;
    position: fixed;
    top: 0;
    left: 0;
    right: 0;
    height: 3.5em;
    box-sizing: border-box;
    box-shadow: 0 4px 16px #aaa;
}
#toolbar > .toolbar-spacer {
    flex: 1 1 auto;
    min-width: 1px;
}
#toolbar > .tabs,
#toolbar > label.toolbar-label,
#toolbar > select,
#toolbar > .toolbar-darkmode {
    margin-left: 0;
    margin-right: 0;
}
[data-theme="dark"] #toolbar {
    background: #1a222c;
    border-bottom: 1.5px solid #22334a;
    box-shadow: 0 2px 12px 0 #00b4d8cc;
}
#toolbar > label.toolbar-label {
    margin-left: 2em;
    margin-bottom: 0;
    margin-right: 0.2em;
    font-weight: 500;
    font-size: 1em;
    color: var(--toolbar-label, #333);
    white-space: nowrap;
    transition: color 0.2s;
}
[data-theme="dark"] #toolbar > label.toolbar-label {
    color: #e0e6ef;
}
#toolbar > select {
    font-size: 1em;
    margin-left: 0.5em;
    margin-right: 1em;
    min-width: 8.5em;
    max-width: 14em;
    padding: 0.2em 0.7em;
    border-radius: 6px;
    border: 1px solid #bbb;
    background: var(--toolbar-select-bg, #fff);
    color: var(--toolbar-select-color, #222);
    vertical-align: middle;
}
#toolbar > .tabs {
    margin-left: 1.5em;
    margin-right: 1em;
    display: flex;
    align-items: center;
    gap: 0.5em;
}
#toolbar > div[style*="margin-left:auto"] {
    margin-left: auto !important;
}
@media (max-width: 900px) {
    #toolbar {
        flex-wrap: wrap;
        height: auto;
        padding: 0.7em 0.5em 0.7em 0.5em;
    }
    #toolbar > label.toolbar-label, #toolbar > select {
        margin-top: 0.5em;
        margin-bottom: 0.5em;
    }
}
#sidebar {
    position: fixed;
    top: var(--toolbar-height);
    right: 0;
    width: 400px;
    max-width: 90vw;
    height: calc(100vh - var(--toolbar-height));
    background: var(--sidebar-bg);
    box-shadow: var(--sidebar-shadow);
    z-index: 90;
    transform: translateX(100%);
    transition: transform 0.2s;
    overflow-y: auto;
    padding: 1.5em 1.5em 1em 1.5em;
}
.tabs {
    display: flex;
    gap: 1em;
    background: none;
}
.tab {
    padding: 0.3em 1.2em;
    border-radius: 6px 6px 0 0;
    background: var(--tab-bg);
    cursor: pointer;
    font-weight: 500;
    border: 1px solid var(--tab-border);
    border-bottom: none;
    color: var(--text-color);
}
.tab.active {
    background: var(--tab-active-bg);
    border-bottom: 1px solid var(--tab-active-border);
    color: var(--text-color);
}
.toolbar-label {
    font-size: 1em;
    margin-left: 2em;
    color: var(--text-color);
}
#highlight-select {
    font-size: 1em;
    margin-left: 0.5em;
}
#graph {
    width: 100vw;
    height: calc(100vh - var(--toolbar-height));
    min-height: 300px;
    position: relative;
    overflow: hidden;
}
#graph svg {
    width: 100%;
    height: 100%;
    display: block;
}
#view-performance {
    width: 100vw;
    height: calc(100vh - var(--toolbar-height));
    min-height: 300px;
    position: relative;
    overflow: hidden;
    padding: 0;
    margin: 0;
    display: block;
}
#performance-graph {
    width: 100%;
    height: 100%;
    display: block;
}
.node circle { stroke: var(--node-stroke); stroke-width: 2px; }
.node text { pointer-events: none; font-size: 12px; }
.link { stroke: #999; stroke-opacity: 0.6; }
.tooltip {
    position: absolute;
    text-align: left;
    width: 400px;
    max-width: 90vw;
    max-height: 60vh;
    overflow: auto;
    padding: 10px;
    font: 12px sans-serif;
    background: #fff;
    border: 1px solid #aaa;
    border-radius: 8px;
    pointer-events: none;
    box-shadow: 2px 2px 8px #aaa;
    z-index: 10;
}
pre {
    background: #f0f0f0;
    color: #222;
    padding: 6px;
    border-radius: 4px;
    max-height: 200px;
    overflow: auto;
    white-space: pre;
    font-size: 1em;
    line-height: 1.4;
    font-family: 'Fira Mono', 'Consolas', 'Menlo', 'Monaco', monospace;
}
[data-theme="dark"] pre {
    background: #1e2633;
    color: #e6eaf3;
    box-shadow: 0 2px 8px #1e3a8c44;
    border: 1px solid #3b5ca8;
}
[data-theme="dark"] #sidebar-content pre,
[data-theme="dark"] .sidebar-tab-content pre {
    color: #111 !important;
    background: #f7f7f7 !important;
}
#sidebar-content {
    display: block;
    height: auto;
    min-height: 0;
    margin-bottom: 2.5em;
}
#sidebar-content pre {
    display: block;
    flex: 1 1 auto;
    min-height: 0;
    max-height: calc(100vh - 10em);
    overflow: auto;
    margin-bottom: 1.5em;
    box-sizing: border-box;
    white-space: pre;
    word-break: normal;
}
.sidebar-code-pre {
  display: block;
  flex: 1 1 auto;
  min-height: 0;
  max-height: calc(100vh - 12em);
  overflow: auto;
  margin-bottom: 2.5em;
  box-sizing: border-box;
  background: #f7f7f7;
  padding: 0.7em 1em;
  border-radius: 6px;
  font-family: 'Fira Mono', 'Consolas', 'Menlo', 'Monaco', monospace;
  font-size: 1em;
  line-height: 1.4;
  white-space: pre;
  word-break: normal;
}
[data-theme="dark"] .sidebar-code-pre {
  background: #f7f7f7 !important;
  color: #111 !important;
}
.sidebar-pre {
  white-space: pre-wrap !important;
  overflow-wrap: anywhere !important;
  word-break: break-word !important;
  max-height: 180px;
  overflow: auto;
  background: #f7f7f7;
  padding: 0.7em 1em;
  border-radius: 6px;
  font-family: 'Fira Mono', 'Consolas', 'Menlo', 'Monaco', monospace;
  font-size: 1em;
  line-height: 1.4;
  margin-bottom: 0.7em;
}
[data-theme="dark"] .sidebar-pre {
  background: #f7f7f7 !important;
  color: #111 !important;
}
select {
    background: var(--select-bg);
    color: var(--select-color);
    border: 1px solid var(--select-border);
    border-radius: 4px;
    padding: 0.2em 0.5em;
}
#darkmode-toggle {
    accent-color: #3b5ca8;
}
a {
    color: #1a3fa6;
    text-decoration: underline;
    transition: color 0.2s;
}
a:visited {
    color: #5a3fa6;
}
a:hover {
    color: #0d2a6c;
}
[data-theme="dark"] a {
    color: #6ea8ff;
}
[data-theme="dark"] a:visited {
    color: #b0bfff;
}
[data-theme="dark"] a:hover {
    color: #3b5ca8;
}
.node-selected {
    stroke: red !important;
    stroke-width: 3px !important;
    transition: stroke 0.2s;
    z-index: 10;
}
[data-theme="dark"] .node-selected {
    stroke: red !important;
    stroke-width: 3px !important;
    z-index: 10;
}
.node-selected.node-hovered, .node-hovered.node-selected {
    stroke: red !important;
    stroke-width: 3px !important;
}
.node-selected.node-highlighted, .node-highlighted.node-selected {
    stroke: red !important;
    stroke-width: 3px !important;
}

.node-hovered {
    stroke: #FFD600;
    stroke-width: 4px;
    transition: stroke 0.1s;
    z-index: 9;
}
[data-theme="dark"] .node-hovered {
    stroke: #FFD600;
    stroke-width: 4px;
    z-index: 9;
}

.node-highlighted {
    stroke: #FFD600;
    stroke-width: 4px;
    filter: drop-shadow(0 0 10px #FFD60088);
    transition: stroke 0.2s, filter 0.2s;
}
[data-theme="dark"] .node-highlighted {
    stroke: #00b4d8;
    stroke-width: 4px;
    filter: drop-shadow(0 0 12px #00b4d8cc);
}

.node-highlighted {
    filter: drop-shadow(0 0 8px #2196f3) drop-shadow(0 0 16px #2196f3);
    stroke: #2196f3;
    stroke-width: 4px;
    transition: filter 0.2s, stroke 0.2s;
}
[data-theme="dark"] .node-highlighted {
    filter: drop-shadow(0 0 10px #00b4d8) drop-shadow(0 0 20px #00b4d8);
    stroke: #00b4d8;
    stroke-width: 4px;
}

.node-locator-highlight {
    filter: drop-shadow(0 0 24px 16px #FFD600) !important;
    transition: filter 0.7s cubic-bezier(0.4,0,0.2,1);
    z-index: 10;
}

@media (max-width: 1200px) {
    #toolbar {
        flex-wrap: wrap;
        gap: 1em;
        padding-right: 1em;
    }
}

.toggle-switch {
    position: relative;
    display: inline-block;
    width: 48px;
    height: 28px;
    vertical-align: middle;
}
.toggle-switch input {
    opacity: 0;
    width: 0;
    height: 0;
}
.toggle-slider {
    position: absolute;
    cursor: pointer;
    top: 0; left: 0; right: 0; bottom: 0;
    background: #ccc;
    border-radius: 28px;
    transition: background 0.2s;
}
.toggle-slider:before {
    position: absolute;
    content: "";
    height: 22px;
    width: 22px;
    left: 3px;
    bottom: 3px;
    background: #fff;
    border-radius: 50%;
    transition: transform 0.2s;
    box-shadow: 0 2px 6px #0002;
}
.toggle-switch input:checked + .toggle-slider {
    background: #3b5ca8;
}
.toggle-switch input:checked + .toggle-slider:before {
    transform: translateX(20px);
    background: #e6eaf3;
}
[data-theme="dark"] .toggle-slider {
    background: #444;
}
[data-theme="dark"] .toggle-switch input:checked + .toggle-slider {
    background: #6ea8ff;
}
[data-theme="dark"] .toggle-switch input:checked + .toggle-slider:before {
    background: #23272a;
}

